// Rule L5: a statement call passes its receivers last, the return value's first; a receiver nobody declared is
// declared by the call.
/// @asset Path(Game, "Functions/MF_MgTwoOut")
extern float3 MF_MgTwoOut(float3 Colour, float Gain = 1.0, out float Weight);

/// @custom
float Halve(float value)
{ return value * 0.5; }

/// @name DreamShaderTests/Migrate/M_MgReceivers
export void M_MgReceivers(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float W;
    // both receivers undeclared, the optional input left out
    float3 Shaded = MF_MgTwoOut(float3(1.0, 0.5, 0.25), Weight = W);
    float Halved = 0;
    Halved = Halve(W);
    Color = Shaded;
    Alpha = Halved;
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
